import{z as A,x as s,o as t,c as p,q as n,j as i,D as e,d as o,s as l,S as r}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"P-tuning v2","description":"","frontmatter":{"title":"P-tuning v2","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/p-tuning-v2.md","filePath":"llm/p-tuning-v2.md","lastUpdated":1791413859000}'),B={name:"llm/p-tuning-v2.md"};function d(m,a,u,h,T,_){const E=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=n('<h1 id="p-tuning-v2" tabindex="-1">P-tuning v2 <a class="header-anchor" href="#p-tuning-v2" aria-label="Permalink to &quot;P-tuning v2&quot;">​</a></h1><div class="epigraph"><p>可训练的不是任务描述句子，而是插在每一层的前缀键值；深度提示让提示调参在大模型与硬任务上追上全参微调的量级。</p><footer>—— Liu 等，P-Tuning v2: Prompt Tuning Can Be Comparable to Fine-tuning Universally Across Scales and Tasks，ACL 2022</footer></div><p><a href="/llm/bitfit">BitFit</a> 不改 \\(W\\)，只平移激活。提示调参也不改 \\(W\\)，但在序列前端（或每层）插入可学习的「虚 token」。Liu 等人的 P-Tuning v2 针对 v1 / Lester 式 Prompt Tuning 的失败：只在输入嵌入层加前缀，小模型或难任务上远弱于全参。v2 把前缀做到每一层的注意力，作为深度提示。缺口：与 <a href="/llm/lora">LoRA</a> 同属 PEFT，但侵入的是 KV 缓存与序列长度，不是矩阵加法。后课合并冲突默认你已能区分「适配器」与「前缀」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>离散 prompt 要人工写；连续 prompt 把 \\(n\\) 个虚向量当参数，经嵌入层进入注意力。只插在第 0 层时，后续层看到的是被冻结 Transformer 变换过的提示，能调控的自由度随深度衰减。大模型上 Lester 等人曾显示仅输入前缀就够；中小模型与序列标注上不够。P-Tuning v2 要恢复深度上的控制：每层自己的前缀 KV，使注意力在每一层都能「看见」任务提示。</p><p><span class="marginnote">术语翻译：「连续 prompt / 虚 token」就是一段不对应任何词表词条、直接以可训练向量的形式存在的「隐形提示词」。它不是文字，优化器可以直接对它求梯度，所以不用纠结怎么用自然语言描述任务。</span></p>',6)),(t(),i(r,null,{default:e(()=>[l(E,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20V1%5B%22v1%3A%20%E5%8F%AA%E5%9C%A8%E5%B5%8C%E5%85%A5%E5%B1%82%E6%8F%92%E5%89%8D%E7%BC%80%22%5D%0A%20%20%20%20A0%5B%22%E7%AC%AC%200%20%E5%B1%82%3A%20%E5%89%8D%E7%BC%80%E5%8F%AF%E8%A7%81%22%5D%20--%3E%20A1%5B%22%E7%AC%AC%201%20%E5%B1%82%22%5D%20--%3E%20A2%5B%22%E2%80%A6%E6%B7%B1%E5%B1%82%E8%A2%AB%E5%86%BB%E7%BB%93%E5%8F%98%E6%8D%A2%E9%80%90%E5%B1%82%E7%A8%80%E9%87%8A%3Cbr%3E%E8%B0%83%E6%8E%A7%E5%8A%9B%E9%9A%8F%E6%B7%B1%E5%BA%A6%E8%A1%B0%E5%87%8F%22%5D%0A%20%20end%0A%20%20subgraph%20V2%5B%22v2%3A%20%E6%AF%8F%E5%B1%82%E9%83%BD%E6%8F%92%E5%89%8D%E7%BC%80%20KV%22%5D%0A%20%20%20%20B0%5B%22%E7%AC%AC%200%20%E5%B1%82%E5%89%8D%E7%BC%80%22%5D%20--%3E%20B1%5B%22%E7%AC%AC%201%20%E5%B1%82%E5%89%8D%E7%BC%80%22%5D%20--%3E%20B2%5B%22%E2%80%A6%E6%AF%8F%E5%B1%82%E6%B3%A8%E6%84%8F%E5%8A%9B%3Cbr%3E%E9%83%BD%E8%83%BD%E9%87%8D%E6%96%B0%E8%AF%BB%E5%88%B0%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20end%0A%20%20V1%20--%20%22%E5%B0%8F%E6%A8%A1%E5%9E%8B%2F%E9%9A%BE%E4%BB%BB%E5%8A%A1%E4%B8%8D%E5%A4%9F%E7%94%A8%22%20--%3E%20V2%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<p>指令 LLM 还有<a href="/llm/chat-template">chat template</a>：真实特殊 token 与虚前缀并存。虚前缀不进词表、不进用户可见字符串，但占序列位置、进 KV。推理必须加载同一份前缀，否则条件 OOD——与模板不一致同构。</p><h3 id="前缀长度是序列税-不是参数税" tabindex="-1">前缀长度是序列税，不是参数税 <a class="header-anchor" href="#前缀长度是序列税-不是参数税" aria-label="Permalink to &quot;前缀长度是序列税，不是参数税&quot;">​</a></h3><p>\\(n\\) 个前缀 token 每层增加 \\(n\\) 的 KV。长上下文里这与<a href="/llm/long-context-finetune">长微调</a>抢预算。LoRA 合并后不占序列。任务极多时，前缀按任务存小，但 decode 每步都要带着任务 KV。这是服务差异，不是准确率差异。</p><p><span class="marginnote">原文覆盖 NLU 与序列标注，强调「跨尺度、跨任务可与微调相比」。生成式助手 SFT 上，实践更常选 LoRA；P-tuning 仍是合法 PEFT，尤其在不能改权重文件、只能加前缀缓存时。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每层注意力，拼接可学习前缀 \\(P_K,P_V\\)（长度 \\(n\\)）到真实序列的 K、V 上，再做 SDPA。参数量约 \\(L\\times n\\times d\\) 量级（或再经小 MLP 重参数化，v1 常用）。冻结原 \\(W\\)。初始化前缀为小随机，避免初期注意力全被前缀吸走。学习率偏适配器侧。SFT 时<a href="/llm/response-only-loss">仅回复损失</a>只在真实助手 token 上；前缀位置始终是条件，不计损失。</p><p>与对话模板：先渲染 messages，再在模型内部插前缀，不要把前缀写成用户可见的「系统提示替代」——除非你有意让二者合一。推理 <code>add_generation_prompt</code> 仍按模板；前缀作为额外 KV 加载。</p>',7)),(t(),i(r,null,{default:e(()=>[l(E,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22chat%20template%20%E7%9C%9F%E5%AE%9E%20token%22%5D%20--%3E%20ATT%5B%22%E6%AF%8F%E5%B1%82%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20P%5B%22%E5%8F%AF%E5%AD%A6%E4%B9%A0%E5%89%8D%E7%BC%80%20KV%22%5D%20--%3E%20ATT%0A%20%20ATT%20--%3E%20Y%5B%22%E4%BB%85%E5%9B%9E%E5%A4%8D%E6%8D%9F%E5%A4%B1%E5%9C%A8%E7%9C%9F%E5%AE%9E%E5%8A%A9%E6%89%8B%E4%B8%8A%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<p>\\(n\\) 从 8–64 扫。过大则过拟合短指令，且税重。可与 LoRA 同用，但很难归因，默认二选一做主。</p><p><span class="marginnote">数字实例：前缀参数量约 \\(L\\times n\\times d\\)。取 24 层、\\(n=20\\)、\\(d=2048\\)，约 \\(24\\times 20\\times 2048\\approx 98\\) 万参数——不到全参微调的千分之一，这正是「参数税」极小的一面；但 KV 侧每层多 20 个位置，是「序列税」的另一面。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>前缀 KV 提供与位置无关（或有独立位置编码）的任务记忆：查询真实 token 时可以读到这些键。深度前缀让每一层都能重新读任务，不依赖第 0 层把提示信息无损传下去。这比 BitFit 更能引入「新的可寻址记忆」，比 LoRA 更少改内容通道 \\(W\\)。失败时表现为：模型会说对任务口头禅，却改不好计算，因为 FFN 权重冻结。</p><p>多任务切换只换前缀 KV，基座唯一。前缀之间相加没有良好定义——应切换而不是平均，除非做了专门的组合训练。这点接到<a href="/llm/lora-merge-conflict">LoRA 合并</a>：前缀冲突同样存在，只是发生在 KV 里。</p><p><span class="marginnote">P-tuning 不替代系统提示。系统提示是离散、人写、进模板的；前缀是连续、训练出来的。混用时两者都是条件，调试要对齐加载。</span></p><p><span class="marginnote">常见误区：初学者容易以为两个任务的前缀可以像 LoRA 权重那样「平均」出一个通用前缀。前缀作用在注意力的 KV 空间里，相加或平均没有良好定义，通常表现为两头任务都变差——正确做法是按任务<strong>切换</strong>前缀，除非专门做过组合训练。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>权重必须能在每层注入前缀接口；闭源 API 做不到 v2。生成长度很长时，前缀占的 KV 恒定，相对税下降，但首包延迟仍在。领域术语内化仍弱，应 <a href="/llm/domain-adaptation-ft">DAPT</a> 或 LoRA。v2 论文早于 ChatGPT 对话栈，迁移时把「CLS 头」换成 LM 头即可，不要复用分类超参当生成超参。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>P-Tuning v2 在每一层插入可学习前缀 KV，冻结 \\(W\\)。</li><li>深度提示补上「只在嵌入层加 prompt」的表达力缺口。</li><li>前缀占序列与 KV，服务税与 LoRA 不同。</li><li>损失不计前缀位置；须与 chat template 一起加载。</li><li>适合多任务切前缀、不能写权重时；生成 SFT 默认仍常选 LoRA。</li><li>出处：Liu 等，P-Tuning v2，ACL 2022。</li></ul>',11))])}const P=A(B,[["render",d]]);export{g as __pageData,P as default};
